effect.shader:
void main() {
vec2 uv = acScreenNorm;
vec2 texSize = max(inputImg.size, vec2(1.0));
vec2 px = vec2(1.0) / texSize;
float c1 = dot(texture2DCv(inputImg.texture, uv - px).rgb, vec3(0.333));
float c2 = dot(texture2DCv(inputImg.texture, uv + px).rgb, vec3(0.333));
float edge = abs(c1 - c2);
vec4 base = texture2DCv(inputImg.texture, uv);
if (edge > threshold * 0.1) {
gl_FragColor = mix(base, vec4(color.rgb, base.a), edge * 5.0);
} else {
gl_FragColor = base;
}
}
